use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Truncates shell output and creates a temporary file if needed"] pub fn truncate_shell_output (stdout : & str , stderr : & str , prefix_lines : usize , suffix_lines : usize , max_line_length : usize ,) -> TruncatedShellOutput { let stdout_result = process_stream (stdout , prefix_lines , suffix_lines , max_line_length) ; let stderr_result = process_stream (stderr , prefix_lines , suffix_lines , max_line_length) ; TruncatedShellOutput :: default () . stderr (Stderr { head : stderr_result . output . head , tail : stderr_result . output . tail , total_lines : stderr_result . total_lines , head_end_line : stderr_result . output . prefix_end_line , tail_start_line : stderr_result . output . suffix_start_line , tail_end_line : stderr_result . output . suffix_end_line , truncated_lines_count : stderr_result . output . truncated_lines_count , }) . stdout (Stdout { head : stdout_result . output . head , tail : stdout_result . output . tail , total_lines : stdout_result . total_lines , head_end_line : stdout_result . output . prefix_end_line , tail_start_line : stdout_result . output . suffix_start_line , tail_end_line : stdout_result . output . suffix_end_line , truncated_lines_count : stdout_result . output . truncated_lines_count , }) }